def P(i,x,y,ball=False):
    d={"id":i,"team":"X" if i.startswith("x") else "O","x":x,"y":y}
    if ball: d["ball"]=True
    return d
def A(t,f,path=None,to=None):
    d={"type":t,"from":f}
    if path: d["path"]=path
    if to: d["to"]=to
    return d
def S(c,p,a): return {"caption":c,"players":p,"actions":a}
def item(i,name,level,leagues,desc,points,src,srcName,tags,steps=None,court="half",note=None,players="5 על 5"):
    d=dict(kind="play",category="End of Game",name=name,level=level,players=players,leagues=leagues,minutes=None,description=desc,points=points,source=src,sourceName=srcName,tags=tags)
    if steps: d["diagram"]={"court":court,"steps":steps}
    if note: d["sourceNote"]=note
    return {"id":i,"data":d}
